from pathlib import Path
import base64

# ART-ATLAS-V4: визуальный слой в стиле утверждённого пользователем референса.
ATLAS_B64 = ''''''

ROOT = Path('.')
atlas = base64.b64decode(ATLAS_B64.encode('ascii')).decode('latin1')
# Собираем JS из компактного шаблона. Latin-1 сохраняет байты 1:1.
js = '''/* ART-ATLAS-V4 — новый визуальный слой по референсу пользователя. */
(function(){
if(window.__ART_ATLAS_V4)return;window.__ART_ATLAS_V4=true;
const SHEET='data:image/webp;base64,__SHEET__';
const names=['shadow','hunter','mutant','bones','elite','boss','start','ordinary','treasure','shop','forge','tavern','sanctuary','cursed','library','altar','trap','labyrinth','portal','bossroom','eliteroom','event'];
const idx={};names.forEach((n,i)=>idx[n]=i);
function v4Tile(n){const i=idx[n];if(i==null)return '';return 'background-image:url("'+SHEET+'");background-size:400% 600%;background-position:'+((i%4)*100/3)+'% '+(Math.floor(i/4)*100/5)+'%;background-repeat:no-repeat;';}
function setScene(id,key){const s=document.querySelector('#'+id+' .scene');if(!s)return;s.style.cssText+=v4Tile(key);s.style.backgroundSize='cover';s.style.backgroundPosition='center';}
function roomKeyV4(){const c=String(typeof abyssRoomContent!=='undefined'?abyssRoomContent:'');if(c.includes('Кровавый алтарь'))return'altar';if(c.includes('Забытый тайник'))return'treasure';if(c.includes('Источник Бездны'))return'portal';if(c.includes('Босс:'))return'bossroom';if(c.includes('Элитный враг:'))return'eliteroom';if(c.includes('Пустой проход')||c.includes('Побеждён'))return'ordinary';return'labyrinth';}
function updateScenesV4(){setScene('main','start');setScene('shop','shop');setScene('tavern','tavern');setScene('equipment','forge');setScene('stats','library');setScene('journal','ordinary');setScene('death','cursed');const a=document.getElementById('abyss');if(a&&!a.classList.contains('hidden'))setScene('abyss',roomKeyV4());}
function installBattleV4(){const old=window.updateBattle;if(typeof old!=='function'||old.__artV4)return false;function wrapped(){old.apply(this,arguments);const b=document.getElementById('enemyArt');if(!b)return;let k='shadow';if(typeof enemy!=='undefined'&&enemy){if(enemy.isBoss)k='boss';else if(enemy.isElite)k='elite';else k=({'Теневой зверь':'shadow','Заражённый охотник':'hunter','Мутант пустоши':'mutant','Пожиратель костей':'bones'})[enemy.name]||'shadow';}b.innerHTML='<span class="atlas-creature-v4" style="'+v4Tile(k)+'"></span>';const e=b.firstElementChild;if(e){e.style.display='block';e.style.width='min(86vw,300px)';e.style.height='min(86vw,220px)';e.style.margin='auto';e.style.backgroundSize='cover';e.style.backgroundPosition='center';e.style.border='1px solid rgba(45,125,170,.65)';e.style.boxShadow='0 0 22px rgba(0,70,110,.28)';}}wrapped.__artV4=true;window.updateBattle=wrapped;return true;}
function installAbyssV4(){const old=window.updateAbyss;if(typeof old!=='function'||old.__artV4)return false;function wrapped(){old.apply(this,arguments);setTimeout(updateScenesV4,0);}wrapped.__artV4=true;window.updateAbyss=wrapped;return true;}
function installScreenV4(){const old=window.setScreen;if(typeof old!=='function'||old.__artV4)return false;function wrapped(){old.apply(this,arguments);setTimeout(updateScenesV4,0);}wrapped.__artV4=true;window.setScreen=wrapped;return true;}
function bootV4(){installBattleV4();installAbyssV4();installScreenV4();updateScenesV4();}
setInterval(bootV4,300);document.addEventListener('DOMContentLoaded',bootV4);
})();
'''.replace('__SHEET__',base64.b64encode(atlas.encode('latin1')).decode('ascii'))
for rel in ['NEW_DARK_RPG/art-atlas-v4.js','android/app/src/main/assets/art-atlas-v4.js']:
    p=ROOT/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(js,encoding='utf-8')
for rel in ['NEW_DARK_RPG/index.html','android/app/src/main/assets/index.html']:
    p=ROOT/rel;s=p.read_text(encoding='utf-8');tag='<script src="art-atlas-v4.js"></script>'
    if tag not in s:
        marker='<script src="art-atlas-v3.js"></script>'
        if marker in s:s=s.replace(marker,marker+'\n'+tag,1)
        elif '</body>' in s:s=s.replace('</body>',tag+'\n</body>',1)
        else:s+='\n'+tag+'\n'
        p.write_text(s,encoding='utf-8')
print('ART-ATLAS-V4 installed')
